interface DrawerToast {
  type: 'success' | 'danger';
  message: string;
}

/* -------------------------------------------------------------------------------------------------
 * DrawerNotifyContext — exposes the in-drawer toast setter so deep descendants
 * (footer action buttons) can report success/error without prop drilling.
 * -----------------------------------------------------------------------------------------------*/

type DrawerNotify = (toast: DrawerToast) => void;

export const DrawerNotifyContext = React.createContext<DrawerNotify | null>(null);

const useDrawerNotify = () => {
  const ctx = React.useContext(DrawerNotifyContext);
  if (!ctx) {
    throw new Error('useDrawerNotify must be used within AssetDetails');
  }
  return ctx;
};

/* -------------------------------------------------------------------------------------------------
 * AssetOperationsContext — drawer-scoped mutations + their pending state, so
 * leaf buttons (Delete, Replace) consume them without prop drilling and the
 * full-drawer busy overlay reads a single flag.
 * -----------------------------------------------------------------------------------------------*/

interface AssetOperations {
  replaceAsset: (file: globalThis.File) => Promise<void>;
  deleteAsset: () => Promise<void>;
  isReplacing: boolean;
  isDeleting: boolean;
}

export const AssetOperationsContext = React.createContext<AssetOperations | null>(null);

const useAssetOperation = () => {
  const ctx = React.useContext(AssetOperationsContext);
  if (!ctx) {
    throw new Error('useAssetOperation must be used within AssetDetails');
  }
  return ctx;
};

/* -------------------------------------------------------------------------------------------------
 * useAssetDetailsParam - read and write the open asset in URL ?{ASSET_DETAILS_URL_PARAM}={id}
 * -----------------------------------------------------------------------------------------------*/

export const useAssetDetailsParam = () => {
  const [{ query }, setQuery] = useQueryParams<{
    [ASSET_DETAILS_URL_PARAM]?: string;
    _q?: string;
  }>();

  const assetId = parseAssetDetailsId(query?.[ASSET_DETAILS_URL_PARAM]);

  // Closing is driven by removing the URL param (a navigation), so navigation
  // guards like <Blocker> can intercept it.
  const openDetails = React.useCallback(
    (id: number) => {
      setQuery(
        withEncodedUserParams(query, { [ASSET_DETAILS_URL_PARAM]: String(id) }),
        'push',
        true
      );
    },
    [query, setQuery]
  );

  const closeDetails = React.useCallback(() => {
    setQuery(withEncodedUserParams(query, { [ASSET_DETAILS_URL_PARAM]: undefined }), 'push', true);
  }, [query, setQuery]);

  return { assetId, openDetails, closeDetails };
};

/* -------------------------------------------------------------------------------------------------
 * useDrawerPresence - keep the drawer mounted through its slide-out
 * -----------------------------------------------------------------------------------------------*/

const useDrawerPresence = (assetId: number | null) => {
  const isVisible = assetId !== null;

  // `isMounted` stays true once opened and only flips false when the close
  // animation actually ends (see onCloseAnimationEnd), so the close duration
  // lives entirely in CSS — no JS timer. The last id is kept so the content
  // doesn't go blank mid-slide.
  const [isMounted, setIsMounted] = React.useState(isVisible);
  const displayAssetId = React.useRef<number | null>(assetId);

  React.useEffect(() => {
    if (assetId !== null) {
      displayAssetId.current = assetId;
      setIsMounted(true);
    }
  }, [assetId]);

  const onCloseAnimationEnd = React.useCallback(
    (event: React.AnimationEvent) => {
      // Ignore animations bubbling up from descendants, and the slide-in.
      if (event.target === event.currentTarget && !isVisible) {
        setIsMounted(false);
      }
    },
    [isVisible]
  );

  return {
    displayAssetId: isVisible ? assetId : displayAssetId.current,
    isVisible,
    shouldRender: isMounted,
    onCloseAnimationEnd,
  };
};

