/**
 * Map the drawer-scoped mutation flags to a single i18n message for the busy
 * overlay loader. Returns `null` when nothing is in flight.
 *
 * Exported for the unit test: the branch order only matters when two flags are
 * true at once, which the UI makes hard to stage through the rendered drawer
 * (each trigger disables itself while its own mutation runs).
 */
export const getBusyMessage = (state: {
  isDeleting: boolean;
  isReplacing: boolean;
  isCropCopying: boolean;
}): { id: string; defaultMessage: string } | null => {
  if (state.isDeleting) {
    return {
      id: getTranslationKey('asset-details.delete.loading'),
      defaultMessage: 'Deleting the file…',
    };
  }
  if (state.isCropCopying) {
    return {
      id: getTranslationKey('asset-details.crop.loading'),
      defaultMessage: 'Saving the copy…',
    };
  }
  if (state.isReplacing) {
    return {
      id: getTranslationKey('asset-details.replace.loading'),
      defaultMessage: 'Replacing the file…',
    };
  }
  return null;
};

const StyledWarning = styled(WarningCircle)`
  width: 1.6rem;
  height: 1.6rem;

  path {
    fill: ${({ theme }) => theme.colors.warning500};
  }
`;

interface DetailFieldProps {
  name: string;
  label: string;
  required?: boolean;
  disabled?: boolean;
}

const DetailField = ({ name, label, required, disabled }: DetailFieldProps) => {
  const { formatMessage } = useIntl();
  const field = useField<string>(name);
  const isSubmitting = useForm('DetailField', (state) => state.isSubmitting);

  // The input is controlled by local state (synchronous, cursor-safe) and the
  // form follows. This was needed when the form context echoed changes back
  // asynchronously: driving the input straight from `field.value` made React
  // rewrite the DOM value after the keystroke, which threw the cursor to the
  // end of the field. The form context now updates synchronously, but the
  // local state is kept as a safe default. The effect below only matters for
  // EXTERNAL value changes (discard/reset), where a cursor jump is fine
  // because the user isn't typing.
  const fieldValue = field.value ?? '';
  const [value, setValue] = React.useState(fieldValue);

  React.useEffect(() => {
    setValue(fieldValue);
  }, [fieldValue]);

  const emptyTooltipLabel = formatMessage(
    {
      id: getTranslationKey('asset-details.field.empty'),
      defaultMessage: '{label} is currently empty.',
    },
    { label }
  );

  return (
    <Field.Root name={name} required={required}>
      <Field.Label>{label}</Field.Label>
      <TextInput
        value={value}
        onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
          setValue(event.target.value);
          field.onChange(name, event.target.value);
        }}
        endAction={
          !value ? (
            <Tooltip label={emptyTooltipLabel}>
              <StyledWarning aria-label={emptyTooltipLabel} role="img" />
            </Tooltip>
          ) : undefined
        }
        type="text"
        disabled={isSubmitting || disabled}
      />
    </Field.Root>
  );
};

/* -------------------------------------------------------------------------------------------------
 * LocationField
 * -----------------------------------------------------------------------------------------------*/

interface LocationFieldProps {
  label: string;
  rootLabel: string;
  folders: Array<{ id: number; name: string }>;
  disabled?: boolean;
}

const LocationField = ({ label, rootLabel, folders, disabled }: LocationFieldProps) => {
  const field = useField<number | null>('folder');
  const isSubmitting = useForm('LocationField', (state) => state.isSubmitting);

  return (
    <Field.Root name="folder" required>
      <Field.Label>{label}</Field.Label>
      {/* `null` is the canonical "root of the Media Library" value everywhere
          in the upload domain. The DS `SingleSelectOption.value` prop is typed
          `string | number`, so we use the empty string as a DOM-only sentinel
          for the root option and map it back to `null` on change. */}
      <SingleSelect
        value={field.value == null ? '' : String(field.value)}
        onChange={(value) => {
          const next = value === '' ? null : Number(value);
          field.onChange('folder', next);
        }}
        disabled={isSubmitting || disabled}
      >
        <SingleSelectOption value="">{rootLabel}</SingleSelectOption>
        {folders.map((folder) => (
          <SingleSelectOption key={folder.id} value={String(folder.id)}>
            {folder.name}
          </SingleSelectOption>
        ))}
      </SingleSelect>
    </Field.Root>
  );
};

