/* -------------------------------------------------------------------------------------------------
 * AssetDetails
 * -----------------------------------------------------------------------------------------------*/

/**
 * Writes whether the form has unsaved edits into the drawer's ref. Only the
 * drawer's close handlers read it, so a ref rather than state: toggling dirty
 * doesn't re-render the drawer. A component, not a hook, because the form state
 * is only reachable inside <Form>'s render prop.
 */
const ReportUnsavedEdits = ({
  target,
  hasUnsavedEdits,
}: {
  target: React.MutableRefObject<boolean>;
  hasUnsavedEdits: boolean;
}) => {
  React.useLayoutEffect(() => {
    target.current = hasUnsavedEdits;

    return () => {
      target.current = false;
    };
  }, [target, hasUnsavedEdits]);

  return null;
};

interface AssetDetailsProps {
  asset: AssetWithPopulatedCreatedBy;
  closeDetails: () => void;
  /** Receives whether the form has unsaved edits. */
  hasUnsavedEditsRef?: React.MutableRefObject<boolean>;
  /** Guard unsaved edits with <Blocker>, for a drawer whose closing is a navigation. */
  guardNavigation?: boolean;
  /** After the asset was updated, replaced or cropped in place, with the server's copy. */
  onAssetChange?: (asset: AssetWithPopulatedCreatedBy) => void;
  /** After the asset was deleted from the library. */
  onAssetDelete?: (id: number) => void;
  /** `location` stamped on the tracking events, for analytics to tell hosts apart. */
  trackedLocation?: string;
}

interface AssetFormState {
  name: string;
  caption: string;
  alternativeText: string;
  folder: number | null;
}

export const AssetDetails = ({
  asset,
  closeDetails,
  hasUnsavedEditsRef,
  guardNavigation = false,
  onAssetChange,
  onAssetDelete,
  trackedLocation = MEDIA_LIBRARY_LOCATION,
}: AssetDetailsProps) => {
  const { formatMessage, formatDate } = useIntl();
  const getErrorMessage = useApiErrorMessage();
  const { canCreate, canUpdate, canDownload, canCopyLink } = useMediaLibraryPermissions();
  const { data: folders = [] } = useGetAllFoldersQuery();
  const { toggleNotification } = useNotification();
  const [updateAsset] = useUpdateAssetMutation();
  const { trackUsage } = useTracking();
  const [replaceMutation, { isLoading: isReplacing }] = useReplaceAssetMutation();
  const [deleteMutation, { isLoading: isDeleting }] = useDeleteAssetMutation();
  const [uploadCroppedCopy, { isLoading: isCropCopying }] = useUploadFileSilentlyMutation();

  const [isCropOpen, setIsCropOpen] = React.useState(false);

  // In-drawer toast slot
  const [drawerToast, setDrawerToast] = React.useState<DrawerToast | null>(null);
  React.useEffect(() => {
    if (!drawerToast) return;
    const timer = window.setTimeout(() => setDrawerToast(null), 5000);
    return () => window.clearTimeout(timer);
  }, [drawerToast]);

  // Local alias matching the DrawerNotifyContext signature, so the drawer's
  // own handlers (replace, update) read like the consumers do.
  const notify = React.useCallback<DrawerNotify>((toast) => setDrawerToast(toast), []);

  const isImage = asset.mime?.includes(ASSET_TYPES.Image);

  // Stable until the asset changes: <Form> resets its values whenever this
  // object does, which on every render would throw away the baseline a save
  // sets and show the pre-save values until the refetch lands.
  const initialValues = React.useMemo<AssetFormState>(
    () => ({
      name: asset.name ?? '',
      caption: asset.caption ?? '',
      alternativeText: asset.alternativeText ?? '',
      folder:
        typeof asset.folder === 'object' && asset.folder !== null
          ? ((asset.folder as { id: number }).id ?? null)
          : ((asset.folder as number | null | undefined) ?? null),
    }),
    [asset.name, asset.caption, asset.alternativeText, asset.folder]
  );

  const handleSubmit = async (
    values: AssetFormState,
    { resetForm }: FormHelpers<AssetFormState>
  ) => {
    const fileInfo = {
      name: values.name,
      caption: values.caption,
      alternativeText: values.alternativeText,
      folder: values.folder,
    };

    const res = await updateAsset({ id: asset.id, fileInfo });

    if ('error' in res) {
      notify({
        type: 'danger',
        message: getErrorMessage(
          res.error,
          formatMessage({
            id: getTranslationKey('asset-details.update.error'),
            defaultMessage: 'Failed to update the file.',
          })
        ),
      });
      return;
    }

    // What was saved is the new baseline. Otherwise the form stays "modified"
    // until the refetched asset resets it, and closing in that gap asks about
    // edits that are already saved.
    resetForm(values);
    onAssetChange?.(res.data);

    trackUsage('didEditMediaLibraryElements', {
      location: trackedLocation,
      // Legacy sends the mime top-level type (image/video/audio/application…).
      type: asset.mime?.split('/')[0],
      changeLocation: values.folder !== initialValues.folder,
    });

    notify({
      type: 'success',
      message: formatMessage({
        id: getTranslationKey('asset-details.update.success'),
        defaultMessage: 'File updated',
      }),
    });
  };

  const { title: folderName } = useFolderInfo(
    typeof asset.folder === 'object' && asset.folder !== null
      ? ((asset.folder as { id: number }).id ?? null)
      : ((asset.folder as number | null | undefined) ?? null)
  );

  // Owns the replace upload so isReplacing can drive the busy overlay.
  const handleReplace = React.useCallback(
    async (file: globalThis.File) => {
      const res = await replaceMutation({ id: asset.id, file, fileInfo: { name: asset.name } });
      if ('error' in res) {
        notify({
          type: 'danger',
          message: getErrorMessage(
            res.error,
            formatMessage({
              id: getTranslationKey('asset-details.replace.error'),
              defaultMessage: 'Failed to replace the file.',
            })
          ),
        });
        return;
      }
      onAssetChange?.(res.data);
      trackUsage('didReplaceMedia', { location: trackedLocation });
      notify({
        type: 'success',
        message: formatMessage({
          id: getTranslationKey('asset-details.replace.success'),
          defaultMessage: 'File replaced.',
        }),
      });
    },
    [
      asset.id,
      asset.name,
      formatMessage,
      getErrorMessage,
      notify,
      onAssetChange,
      replaceMutation,
      trackedLocation,
      trackUsage,
    ]
  );

  // Owns the delete: on error notify in-drawer (drawer stays), on success fire
  // a persistent global notification then close the drawer.
  const handleDelete = React.useCallback(async () => {
    const res = await deleteMutation(asset.id);
    if ('error' in res) {
      notify({
        type: 'danger',
        message: getErrorMessage(
          res.error,
          formatMessage({
            id: getTranslationKey('asset-details.delete.error'),
            defaultMessage: 'Failed to delete the asset.',
          })
        ),
      });
      return;
    }
    toggleNotification({
      type: 'success',
      message: formatMessage(
        {
          id: getTranslationKey('asset-details.delete.success'),
          defaultMessage: '1 element have been deleted from {folderName}',
        },
        { folderName }
      ),
    });
    onAssetDelete?.(asset.id);
    closeDetails();
  }, [
    asset.id,
    closeDetails,
    deleteMutation,
    folderName,
    formatMessage,
    getErrorMessage,
    notify,
    onAssetDelete,
    toggleNotification,
  ]);

  const notifyCropError = (error?: unknown) => {
    notify({
      type: 'danger',
      message: getErrorMessage(
        error,
        formatMessage({
          id: getTranslationKey('asset-details.crop.error'),
          defaultMessage: 'Failed to update the file.',
        })
      ),
    });
  };

  // Apply: replace the original binary with the cropped file + focal point.
  // Close the editor first so the drawer's busy overlay is visible while the
  // mutation runs (the editor renders in a Portal above the drawer).
  const handleCropApply = async (file: globalThis.File, focalPoint: FocalPoint) => {
    setIsCropOpen(false);
    const res = await replaceMutation({
      id: asset.id,
      file,
      fileInfo: { focalPoint },
    });
    if ('error' in res) {
      notifyCropError(res.error);
      return;
    }
    onAssetChange?.(res.data);
    trackUsage('didCropFile', { location: trackedLocation, duplicatedFile: false });
    notify({
      type: 'success',
      message: formatMessage({
        id: getTranslationKey('asset-details.crop.success'),
        defaultMessage: 'File updated',
      }),
    });
  };

  // Save as copy: upload the cropped file as a new asset in the same folder.
  // The original is untouched, so `onAssetChange` stays silent.
  const handleCropSaveAsCopy = async (file: globalThis.File, focalPoint: FocalPoint) => {
    setIsCropOpen(false);
    // Silent single-file upload (no global progress dialog). Carry over the
    // source asset's caption/alt so the copy keeps its metadata.
    const res = await uploadCroppedCopy({
      file,
      fileInfo: {
        name: asset.name,
        caption: asset.caption ?? '',
        alternativeText: asset.alternativeText ?? '',
        folder: initialValues.folder,
        focalPoint,
      },
    });
    if ('error' in res) {
      notifyCropError(res.error);
      return;
    }
    trackUsage('didCropFile', { location: trackedLocation, duplicatedFile: true });
    notify({
      type: 'success',
      message: formatMessage({
        id: getTranslationKey('asset-details.crop.copy-success'),
        defaultMessage: 'Copy created.',
      }),
    });
  };

  const operations = React.useMemo<AssetOperations>(
    () => ({
      replaceAsset: handleReplace,
      deleteAsset: handleDelete,
      isReplacing,
      isDeleting,
    }),
    [handleReplace, handleDelete, isReplacing, isDeleting]
  );

  return (
    // `key={asset.id}` resets the form when the drawer switches to a different
    // asset so cached values from the previous asset don't bleed in.
    <DrawerNotifyContext.Provider value={notify}>
      <AssetOperationsContext.Provider value={operations}>
        <FormShell>
          <Form key={asset.id} method="POST" initialValues={initialValues} onSubmit={handleSubmit}>
            {({ modified, isSubmitting, values, resetForm }) => {
              const nameIsEmpty = ((values as AssetFormState).name ?? '').trim() === '';
              const busyMessage = getBusyMessage({ isDeleting, isReplacing, isCropCopying });
              return (
                <>
                  {/* With `guardNavigation`, every close path (X button, ESC, route
                change, browser back) is a navigation, so <Blocker> intercepts it
                when the form is dirty. `onProceed` resets the form so the held
                navigation can complete. Lives inside <Form> so it can read the
                form context. Without it, the drawer asks on its own close paths. */}
                  {guardNavigation ? (
                    <Blocker onProceed={resetForm} />
                  ) : hasUnsavedEditsRef ? (
                    <ReportUnsavedEdits
                      target={hasUnsavedEditsRef}
                      hasUnsavedEdits={modified && !isSubmitting}
                    />
                  ) : null}
                  {isCropOpen && isImage ? (
                    <AssetCropEditor
                      asset={asset}
                      onClose={() => setIsCropOpen(false)}
                      onApply={handleCropApply}
                      onSaveAsCopy={handleCropSaveAsCopy}
                      canSaveAsCopy={canCreate}
                    />
                  ) : null}
                  {busyMessage ? <BusyOverlay>{formatMessage(busyMessage)}</BusyOverlay> : null}
                  {drawerToast ? (
                    <DrawerToastSlot>
                      <Alert
                        variant={drawerToast.type === 'success' ? 'success' : 'danger'}
                        closeLabel={formatMessage({ id: 'global.close', defaultMessage: 'Close' })}
                        onClose={() => setDrawerToast(null)}
                      >
                        {drawerToast.message}
                      </Alert>
                    </DrawerToastSlot>
                  ) : null}
                  <Drawer.ScrollableContent>
                    <AssetPreview
                      asset={asset}
                      actions={
                        isImage && canUpdate ? (
                          <AssetImageActions onCrop={() => setIsCropOpen(true)} />
                        ) : null
                      }
                    />
                    <Flex
                      direction="column"
                      alignItems="stretch"
                      gap={4}
                      paddingTop={4}
                      paddingBottom={4}
                      paddingLeft={5}
                      paddingRight={5}
                    >
                      <Typography variant="beta" fontWeight="semiBold" tag="h3">
                        {formatMessage({
                          id: getTranslationKey('asset-details.fileInfo'),
                          defaultMessage: 'File info',
                        })}
                      </Typography>
                      <Flex
                        wrap="wrap"
                        gap={4}
                        background="neutral100"
                        paddingTop={4}
                        paddingBottom={4}
                        paddingLeft={6}
                        paddingRight={6}
                        alignItems="flex-start"
                      >
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.creationDate'),
                            defaultMessage: 'Creation date',
                          })}
                          value={
                            asset.createdAt
                              ? formatDate(new Date(asset.createdAt), {
                                  dateStyle: 'long',
                                  timeStyle: 'short',
                                })
                              : null
                          }
                        />
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.lastUpdated'),
                            defaultMessage: 'Last updated',
                          })}
                          value={
                            asset.updatedAt
                              ? formatDate(new Date(asset.updatedAt), {
                                  dateStyle: 'long',
                                  timeStyle: 'short',
                                })
                              : null
                          }
                        />
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.createdBy'),
                            defaultMessage: 'Created by',
                          })}
                          value={
                            asset.createdBy
                              ? (getDisplayName({
                                  firstname: asset.createdBy.firstname ?? undefined,
                                  lastname: asset.createdBy.lastname ?? undefined,
                                  username: asset.createdBy.username ?? undefined,
                                  email: asset.createdBy.email ?? undefined,
                                }) ?? '-')
                              : null
                          }
                        />
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.size'),
                            defaultMessage: 'Size',
                          })}
                          value={asset.size ? formatBytes(asset.size, 1) : null}
                        />
                        {isImage && (asset.width != null || asset.height != null) && (
                          <DetailItem
                            label={formatMessage({
                              id: getTranslationKey('asset-details.dimensions'),
                              defaultMessage: 'Dimensions',
                            })}
                            value={
                              asset.width != null && asset.height != null
                                ? `${asset.width} × ${asset.height}`
                                : null
                            }
                          />
                        )}
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.extension'),
                            defaultMessage: 'Extension',
                          })}
                          value={getFileExtension(asset.ext)}
                        />
                        <DetailItem
                          label={formatMessage({
                            id: getTranslationKey('asset-details.assetId'),
                            defaultMessage: 'Asset ID',
                          })}
                          value={String(asset.id)}
                        />
                      </Flex>
                      <DetailField
                        name="name"
                        label={formatMessage({
                          id: getTranslationKey('asset-details.fileName'),
                          defaultMessage: 'File name',
                        })}
                        required
                        disabled={!canUpdate}
                      />
                      <LocationField
                        label={formatMessage({
                          id: getTranslationKey('asset-details.location'),
                          defaultMessage: 'Location',
                        })}
                        rootLabel={formatMessage({
                          id: getTranslationKey('plugin.home'),
                          defaultMessage: 'Home',
                        })}
                        folders={folders}
                        disabled={!canUpdate}
                      />
                      {/* Caption and alternative text apply to every file type
                          (matches the legacy Media Library), not images only. */}
                      <DetailField
                        name="caption"
                        label={formatMessage({
                          id: getTranslationKey('asset-details.caption'),
                          defaultMessage: 'Caption',
                        })}
                        disabled={!canUpdate}
                      />
                      <DetailField
                        name="alternativeText"
                        label={formatMessage({
                          id: getTranslationKey('asset-details.alternativeText'),
                          defaultMessage: 'Alternative text',
                        })}
                        disabled={!canUpdate}
                      />
                    </Flex>
                  </Drawer.ScrollableContent>
                  {/* Every footer action is permission-gated — when none survive,
                      drop the whole bar instead of showing an empty strip. */}
                  {(canUpdate || canCopyLink || canDownload) && (
                    <Flex
                      justifyContent="space-between"
                      alignItems="center"
                      gap={2}
                      padding={3}
                      borderColor="neutral150"
                      borderStyle="solid"
                      borderWidth="1px 0 0 0"
                      background="neutral0"
                    >
                      <Flex gap={2}>
                        {canUpdate && <DeleteAssetButton />}
                        {canCopyLink && <CopyLinkButton asset={asset} />}
                        {canDownload && <DownloadAssetButton asset={asset} />}
                        {canUpdate && <ReplaceAssetButton mime={asset.mime} />}
                      </Flex>
                      {canUpdate && (
                        <Button
                          type="submit"
                          variant="default"
                          loading={isSubmitting}
                          // File name is required; block submit when it's empty or whitespace so the API can't 400 on a blank value.
                          disabled={!modified || isSubmitting || nameIsEmpty}
                        >
                          {formatMessage({
                            id: getTranslationKey('asset-details.save'),
                            defaultMessage: 'Save changes',
                          })}
                        </Button>
                      )}
                    </Flex>
                  )}
                </>
              );
            }}
          </Form>
        </FormShell>
      </AssetOperationsContext.Provider>
    </DrawerNotifyContext.Provider>
  );
};

/* -------------------------------------------------------------------------------------------------
 * DrawerHeader
 * -----------------------------------------------------------------------------------------------*/

/**
 * The icon's size lives in SVG attributes, which flex is free to override, so a
 * long asset name would squash it. Matches the grid and table rows, where the
 * file-type icon is shrink-proof and the name is what truncates.
 */
const HeaderIcon = styled(Flex)`
  flex-shrink: 0;
`;

const HeaderTitle = styled(Typography)`
  min-width: 0;
`;

interface DrawerHeaderProps {
  asset: AssetWithPopulatedCreatedBy;
  closeDetails: () => void;
}

const DrawerHeader = ({ asset, closeDetails }: DrawerHeaderProps) => {
  const DocIcon = asset ? getAssetIcon(asset.mime, asset.ext) : FileError;
  return (
    <Flex
      gap={2}
      paddingLeft={5}
      paddingTop={3}
      paddingBottom={3}
      paddingRight={3}
      borderColor="neutral150"
      borderStyle="solid"
      borderWidth="0 0 1px 0"
    >
      <HeaderIcon>
        <DocIcon width={20} height={20} />
      </HeaderIcon>
      <Drawer.Title asChild>
        <HeaderTitle variant="omega" fontWeight="semiBold" overflow="hidden" ellipsis tag="h2">
          {asset.name}
        </HeaderTitle>
      </Drawer.Title>
      <Box marginLeft="auto">
        <Drawer.CloseButton onClose={closeDetails}>
          <ArrowLineRight />
        </Drawer.CloseButton>
      </Box>
    </Flex>
  );
};

/* -------------------------------------------------------------------------------------------------
 * DrawerContent
 * -----------------------------------------------------------------------------------------------*/

interface DrawerContentProps {
  assetId: number;
  /** Closes, asking first when there are unsaved edits. */
  requestClose: () => void;
  /** Closes unconditionally, for when the asset itself is gone. */
  closeDetails: () => void;
  hasUnsavedEditsRef: React.MutableRefObject<boolean>;
  guardNavigation: boolean;
  onAssetChange?: (asset: AssetWithPopulatedCreatedBy) => void;
  onAssetDelete?: (id: number) => void;
  trackedLocation?: string;
}

const DrawerContent = ({
  assetId,
  requestClose,
  closeDetails,
  hasUnsavedEditsRef,
  guardNavigation,
  onAssetChange,
  onAssetDelete,
  trackedLocation,
}: DrawerContentProps) => {
  const { formatMessage } = useIntl();
  const {
    data: asset,
    isLoading,
    error,
  } = useGetAssetQuery(assetId, {
    refetchOnMountOrArgChange: false,
    refetchOnReconnect: false,
    refetchOnFocus: false,
  });

  if (isLoading) {
    return (
      <Flex justifyContent="center" padding={8}>
        <Loader>{formatMessage({ id: 'app.loading', defaultMessage: 'Loading...' })}</Loader>
      </Flex>
    );
  }

  if (error || !asset) {
    return (
      <Flex direction="column" alignItems="stretch" gap={4} padding={4}>
        <Alert
          variant="danger"
          closeLabel={formatMessage({ id: 'global.close', defaultMessage: 'Close' })}
          onClose={requestClose}
        >
          {formatMessage({
            id: getTranslationKey('asset-details.error'),
            defaultMessage: 'Failed to load file details.',
          })}
        </Alert>
      </Flex>
    );
  }

  return (
    <>
      <DrawerHeader asset={asset} closeDetails={requestClose} />
      <AssetDetails
        asset={asset}
        closeDetails={closeDetails}
        hasUnsavedEditsRef={hasUnsavedEditsRef}
        guardNavigation={guardNavigation}
        onAssetChange={onAssetChange}
        onAssetDelete={onAssetDelete}
        trackedLocation={trackedLocation}
      />
    </>
  );
};

/* -------------------------------------------------------------------------------------------------
 * AssetDetailsDrawer
 * -----------------------------------------------------------------------------------------------*/

/**
 * Whether a pointer press outside the panel should leave the drawer open.
 *
 * Anywhere on the page behind dismisses it, controls included. Two exceptions,
 * neither of which is "the user meant to stay": the part of an asset's card or
 * row whose `click` switches the drawer rather than closing it — not its own
 * checkbox or actions menu, which act on the item; and a panel already closing,
 * which `forceMount` keeps listening through its animation, where dismissing
 * again would re-trigger the unsaved-changes guard for nothing.
 */
const shouldKeepDrawerOpen = (
  event: { target: EventTarget | null; detail: { originalEvent: { button: number } } },
  isVisible: boolean
) => {
  if (!isVisible) {
    return true;
  }

  // Radix's dismisser fires on any `pointerdown`, secondary buttons included. A
  // right-click is contextual, and with the create menu on the background one
  // press would otherwise both close this and open that.
  if (event.detail.originalEvent.button !== 0) {
    return true;
  }

  if (!(event.target instanceof Element)) {
    return false;
  }

  // The card's own controls — its checkbox, its actions menu — act on the item
  // and stop the card's click, so no switch follows and the press dismisses.
  return (
    event.target.closest(ASSET_DETAILS_TRIGGER_SELECTOR) !== null &&
    event.target.closest(ASSET_ITEM_CONTROL_SELECTOR) === null
  );
};

interface AssetDetailsDrawerProps {
  /** The asset to show, or `null` to close the drawer. */
  assetId: number | null;
  onClose: () => void;
  /**
   * Guard unsaved edits with <Blocker> instead of the drawer's own confirmation.
   * Only for a drawer whose closing is itself a navigation, which <Blocker> then
   * covers along with route changes and browser history. Not for a host that
   * has its own <Blocker>: react-router allows one per page.
   */
  guardNavigation?: boolean;
  /**
   * After the asset was updated, replaced or cropped in place, with the server's
   * copy, so a host holding the asset (e.g. a form field) can stay in sync.
   */
  onAssetChange?: (asset: AssetWithPopulatedCreatedBy) => void;
  /** After the asset was deleted from the library, just before the drawer closes. */
  onAssetDelete?: (id: number) => void;
  /**
   * `location` stamped on the tracking events, for analytics to tell hosts
   * apart. Defaults to the Media Library page's.
   */
  trackedLocation?: string;
}

export const AssetDetailsDrawer = ({
  assetId,
  onClose,
  guardNavigation = false,
  onAssetChange,
  onAssetDelete,
  trackedLocation,
}: AssetDetailsDrawerProps) => {
  const { formatMessage } = useIntl();
  const { displayAssetId, isVisible, shouldRender, onCloseAnimationEnd } =
    useDrawerPresence(assetId);

  const hasUnsavedEditsRef = React.useRef(false);
  const [isConfirmingClose, setIsConfirmingClose] = React.useState(false);
  // Where focus was when the drawer opened — the card or the field's edit
  // button — so closing can hand it back instead of dropping it on <body>.
  const returnFocusRef = React.useRef<HTMLElement | null>(null);

  const requestClose = React.useCallback(() => {
    if (hasUnsavedEditsRef.current) {
      setIsConfirmingClose(true);
      return;
    }
    onClose();
  }, [onClose]);

  if (!shouldRender || displayAssetId === null) {
    return null;
  }

  return (
    <Drawer.Root isVisible={isVisible} onClose={requestClose}>
      {/* Wrapper div required: Dialog.Portal uses asChild and merges ref onto each child.
          VisuallyHidden does not forward refs, so we wrap it in a div that can receive the ref. */}
      <div>
        <VisuallyHidden>
          <Drawer.Title>
            {formatMessage({
              id: getTranslationKey('asset-details.title'),
              defaultMessage: 'File details',
            })}
          </Drawer.Title>
          <Drawer.Description>
            {formatMessage({
              id: getTranslationKey('asset-details.description'),
              defaultMessage: 'Displays file information and metadata',
            })}
          </Drawer.Description>
        </VisuallyHidden>
      </div>
      <Drawer.Body
        animationDirection="left"
        width="41.6rem"
        // dvh, not vh: the drawer is anchored to the bottom, so with 100vh on
        // mobile (where the URL bar shrinks the visual viewport below 100vh)
        // the top of the drawer — header, title, close button — is pushed
        // off-screen. dvh tracks the actual visible height.
        height="100dvh"
        onAnimationEnd={onCloseAnimationEnd}
        // Runs before focus moves in, so this is still the element that opened it.
        onOpenAutoFocus={() => {
          returnFocusRef.current =
            document.activeElement instanceof HTMLElement ? document.activeElement : null;
        }}
        // By now the panel is gone: focus is on <body> unless the user moved it
        // somewhere — a press on another control dismissed the drawer — and that
        // choice wins.
        onCloseAutoFocus={(event) => {
          const target = returnFocusRef.current;
          const active = document.activeElement;
          if (target?.isConnected && (active === null || active === document.body)) {
            event.preventDefault();
            target.focus();
          }
        }}
        // Opt in to dismiss-on-outside-click; it goes through `requestClose`,
        // like the header's close button, so unsaved edits are still guarded.
        onPointerDownOutside={(event) => {
          if (shouldKeepDrawerOpen(event, isVisible)) {
            event.preventDefault();
          }
        }}
      >
        <DrawerContent
          assetId={displayAssetId}
          requestClose={requestClose}
          closeDetails={onClose}
          hasUnsavedEditsRef={hasUnsavedEditsRef}
          guardNavigation={guardNavigation}
          onAssetChange={onAssetChange}
          onAssetDelete={onAssetDelete}
          trackedLocation={trackedLocation}
        />
        {/* Rendered from inside the panel so Radix counts presses on it as
            inside, and the drawer stays put while it is open. The edits go
            with the form, which unmounts once the drawer has closed. */}
        <Dialog.Root open={isConfirmingClose} onOpenChange={setIsConfirmingClose}>
          <ConfirmDialog onConfirm={onClose} variant="danger">
            {formatMessage({
              id: getTranslationKey('asset-details.unsaved.confirm'),
              defaultMessage:
                "You have unsaved changes, are you sure you want to close this file's details? Your changes will be lost.",
            })}
          </ConfirmDialog>
        </Dialog.Root>
      </Drawer.Body>
    </Drawer.Root>
  );
};

/**
 * The drawer bound to the URL's `?assetId=`, as the Media Library page uses it:
 * linkable, survives a refresh, and closing is a navigation.
 */
export const AssetDetailsDrawerFromUrl = () => {
  const { assetId, closeDetails } = useAssetDetailsParam();

  return <AssetDetailsDrawer assetId={assetId} onClose={closeDetails} guardNavigation />;
};
